import{_ as o,l as s,o as e,c as i,v as t,p as n,x as r,d as c,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"多级 TLB 与页表缓存","description":"","frontmatter":{"title":"多级 TLB 与页表缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tlb-hierarchy-pwc.md","filePath":"cs/tlb-hierarchy-pwc.md","lastUpdated":1789023840000}'),T={name:"cs/tlb-hierarchy-pwc.md"};function B(p,a,P,L,m,A){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="多级-tlb-与页表缓存" tabindex="-1">多级 TLB 与页表缓存 <a class="header-anchor" href="#多级-tlb-与页表缓存" aria-label="Permalink to &quot;多级 TLB 与页表缓存&quot;">​</a></h1><div class="epigraph"><p>L1 TLB 要小而快，覆盖不住就下到 L2 TLB；再缺失则走页表，页表缓存把中间层 PTE 留住，避免每次从根走四次访存。</p><footer>—— 据 Barr, Cox, and Rixner, Translation Caching, MICRO 2010；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/write-combining">上一课</a> 的合并在 PA 上进行。<a href="/cs/tlb-translate">TLB 翻译</a> 已给出一次查找。VIPT 与大工作集让 L1 TLB 覆盖成为瓶颈：4KiB 页 × 64 项只有 256KiB 的 VA。本课不重讲 walk 的四级格式。缺口是<strong>TLB 层次 + 页表缓存（PWC / MMU cache）</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每个 load 都要 VA→PA。L1 TLB 全相联或小组相联，项数有限。缺失若直接走内存中的页表，<a href="/cs/sv39-page-table">Sv39</a> 一类要多次依赖访存，MLP 帮不上这条链。缺口不是更大的 L1D，而是<strong>二级 TLB 放大覆盖，以及把页表中间节点缓存在 MMU 旁。</strong></p><p><span class="marginnote">PWC：缓存非叶 PTE，下一次 walk 可以从中间层开始。Barr–Cox–Rixner 比较了各种 translation cache 的组织。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>L1 TLB：分 I/D，低延迟。L2 TLB：更大，统一或分裂，缺失才 walk。Walk：硬件有限状态机读 PTE；每层可查 PWC。ASID 命中避免切换全冲。全局页可跨 ASID 保留。</p>',8)),(e(),n(d,null,{default:r(()=>[h(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22VA%22%5D%20--%3E%20L1T%5B%22L1%20TLB%22%5D%0A%20%20L1T%20--%3E%7C%22%E7%BC%BA%E5%A4%B1%22%7C%20L2T%5B%22L2%20TLB%22%5D%0A%20%20L2T%20--%3E%7C%22%E7%BC%BA%E5%A4%B1%22%7C%20PWC%5B%22PWC%20%E4%B8%AD%E9%97%B4%E5%B1%82%22%5D%0A%20%20PWC%20--%3E%20MEM%5B%22%E8%AF%BB%E5%86%85%E5%AD%98%20PTE%22%5D%0A%20%20MEM%20--%3E%20FILL%5B%22%E5%A1%AB%20TLB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TLB miss 的 CPI 可以超过 cache miss：因为它串在地址生成之后、cache 访问之前（PIPT）或并行失败时（VIPT 标签等 PPN）。<a href="/cs/mlp-memory-parallelism">MLP</a> 对 walk 内部的串行读几乎无效。大页下一课用一项覆盖更多 VA，直接减 miss。</p><p>Shootdown：<a href="/cs/tlb-shootdown">tlb-shootdown</a> 必须覆盖所有级与 PWC，否则别名与过期 PPN。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把软件 fill（老 RISC）当当代主干。也不把嵌套虚拟化的二次 walk 写完（EHT/EPT），只承认会成倍放大 PWC 的价值。大页覆盖是下一课专门的几何。</p><p>后课默认：翻译有 L1/L2 TLB 与 PWC。同一项能盖住 2MiB 而不是 4KiB 时，覆盖率的账完全改写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多级 TLB 分层延迟与覆盖；PWC 截短页表游走。</li><li>walk 是串行访存，MLP 难救。</li><li>大页用一项扩大覆盖，是下一课。</li><li>出处：Barr, Cox, Rixner, <em>MICRO</em>, 2010；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const E=o(T,[["render",B]]);export{_ as __pageData,E as default};
